}
for cat,pat in patterns.items():
 hits=collections.defaultdict(list); total=0
 for info in z.infolist():
  if info.file_size>2_000_000 or info.filename.startswith('bin/'): continue
  try:s=z.read(info).decode('utf-8','replace')
  except:continue
  for i,line in enumerate(s.splitlines(),1):
   if pat.search(line):
    total+=1
    if len(hits[info.filename])<8: hits[info.filename].append((i,line.strip()[:180]))
 print('\\n===',cat,'TOTAL',total,'FILES',len(hits),'===')
 for f,rows in list(hits.items())[:80]:
